export function buildAction03Prompt(
  context: Action03PromptContext
): string {
  const {
    bottleneckPatterns,
    timeSeriesData,
    reportFormat,
    highlightCritical,
    dateRange,
  } = context;

  const criticalPatterns = bottleneckPatterns.filter(
    (p) => p.severity === "critical"
  );
  const trendingPatterns = bottleneckPatterns.filter(
    (p) => p.trend === "increasing"
  );

  const systemPrompt = `You are an expert data visualization and analysis specialist for bottleneck pattern reporting.

Your task is to create a comprehensive visualization report that transforms raw bottleneck pattern data into actionable insights.

## Input Data Summary
- Total Patterns Analyzed: ${bottleneckPatterns.length}
- Critical Patterns: ${criticalPatterns.length}
- Trending Up (Increasing): ${trendingPatterns.length}
- Date Range: ${dateRange.startDate} to ${dateRange.endDate}
- Report Format: ${reportFormat}
- Highlight Critical Issues: ${highlightCritical}

## Bottleneck Patterns to Visualize
${bottleneckPatterns
  .map(
    (pattern) => `
- Pattern ID: ${pattern.patternId}
  Category: ${pattern.category}
  Occurrences: ${pattern.occurrenceCount}
  Severity: ${pattern.severity}
  Trend: ${pattern.trend}
  Affected Teams: ${pattern.affectedTeams.join(", ")}
  First Detected: ${pattern.firstDetected}
  Last Detected: ${pattern.lastDetected}
`
  )
  .join("")}

## Time Series Data Points
${timeSeriesData
  .slice(0, 10)
  .map(
    (point) => `
- Timestamp: ${point.timestamp}
  Pattern: ${point.patternId}
  Occurrences: ${point.occurrenceCount}
  Resolved: ${point.resolvedCount}
  Avg Resolution Time: ${point.averageResolutionTime}h
`
  )
  .join("")}

## Visualization Requirements

### 1. Time Series Chart
- Show pattern occurrence trends over the date range
- Highlight critical patterns with distinct visual emphasis
- Include resolution rate overlay if available
- Use appropriate chart type (line for trends, bar for comparisons)

### 2. Category Breakdown
- Distribute patterns by category
- Show percentage contribution of each category
- Rank by frequency and impact

### 3. Severity Distribution
- Visualize distribution across severity levels (low, medium, high, critical)
- Highlight concentration of critical issues
- Show trend direction for each severity level

### 4. Team Impact Matrix
- Map which teams are affected by which patterns
- Show intensity of impact (frequency × severity)
- Identify teams with highest burden

## Analysis Requirements

### Insights to Generate
1. Identify the top 3 most impactful bottleneck patterns
2. Detect emerging patterns (newly appearing or rapidly increasing)
3. Identify patterns showing improvement (decreasing trend)
4. Analyze cross-team impact and dependencies
5. Assess overall system health based on pattern distribution

### Recommendations to Provide
1. Prioritize by impact (frequency × severity)
2. Suggest intervention strategies for top patterns
3. Estimate implementation effort for each recommendation
4. Project potential impact of addressing each pattern
5. Identify quick wins vs. long-term improvements

## Output Format Requirements

Generate a structured report with:
- Clear summary statistics
- Visual data structures (charts, matrices, breakdowns)
- Actionable insights with evidence
- Prioritized recommendations with effort estimates
- Raw data for further analysis

${
  highlightCritical
    ? `
## Critical Issue Handling
- Flag all critical severity patterns prominently
- Provide immediate action items for critical patterns
- Include escalation recommendations
- Suggest monitoring frequency for critical items
`
    : ""
}

## Quality Checklist
- All patterns are accounted for in visualizations
- Time series data is chronologically ordered
- Recommendations are specific and actionable
- Insights are supported by data
- Report is suitable for executive review
- Format matches requested output (${reportFormat})

Generate the comprehensive visualization report now.`;

  return systemPrompt;
}

